import{spawn}from'node:child_process';
export async function connect(exe){const child=spawn(exe,[],{stdio:['pipe','pipe','pipe'],windowsHide:true});child.stderr.resume();let buffer='',seq=0;const pending=new Map();child.stdout.on('data',b=>{buffer+=b;let end;while((end=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,end);buffer=buffer.slice(end+1);try{const r=JSON.parse(line);const p=pending.get(r.id);if(p){pending.delete(r.id);clearTimeout(p.timer);p.resolve(r);}}catch{}}});child.on('exit',()=>{for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('MCP exited'));}pending.clear();});const request=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;const timer=setTimeout(()=>{pending.delete(id);reject(Error('MCP test response timeout'));},35000);pending.set(id,{resolve,reject,timer});child.stdin.write(JSON.stringify({jsonrpc:'2.0',id,method,params})+'\n');});const initialize=await request('initialize',{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'ownership-compatibility',version:'1'}});child.stdin.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'})+'\n');return {request,initialize,close:()=>child.kill()};}
